from pathlib import Path

root = Path(__file__).resolve().parents[1]
app_path = root / "src" / "App.tsx"
css_path = root / "src" / "App.css"
app = app_path.read_text(encoding="utf-8")

marker = 'const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");\n'
helpers = '''\nconst storefrontCategoryCards = [
  { name: "Glass", icon: "▧", description: "Toughened, decorative, partition and custom glass", action: "products" as Page },
  { name: "Hardware", icon: "⚙", description: "Hinges, bolts, handles, stays and channels", action: "hardware" as Page },
  { name: "Mirrors", icon: "◈", description: "Mirror solutions for homes and commercial spaces", action: "products" as Page },
  { name: "Partitions", icon: "▥", description: "Glass partitions and office solutions", action: "products" as Page },
  { name: "Door & Fittings", icon: "▤", description: "Complete glass door hardware essentials", action: "hardware" as Page },
  { name: "Custom Solutions", icon: "✦", description: "Tell us your requirement and get a quote", action: "services" as Page },
];
'''
if "const storefrontCategoryCards" not in app:
    app = app.replace(marker, marker + helpers)

home_start = app.find('    {page === "home" &&')
products_start = app.find('    {page === "products" &&', home_start)
if home_start < 0 or products_start < 0:
    raise SystemExit("home/products markers not found")
home = '''    {page === "home" && <main className="storefront-home">
      <section className="storefront-hero"><div className="storefront-hero-copy"><p className="storefront-kicker">GLASS • HARDWARE • PROJECT SUPPLIES</p><h1>Everything you need for your glass project.</h1><p>Shop glass products and hardware with clear pricing, live stock and a simple cart-to-checkout experience.</p><div className="storefront-hero-actions"><button className="primary-btn" onClick={() => navigate("products")}>Shop products</button><button className="secondary-btn" onClick={() => navigate("hardware")}>Shop hardware</button></div></div><div className="storefront-hero-image"><img src={glassProduct} alt="Glassmart products"/><div className="storefront-hero-tag"><strong>Ready to order?</strong><span>Pick a product, add it to cart and checkout.</span></div></div></section>
      <section className="storefront-benefits"><div><strong>Fast support</strong><span>Quick help for product and project needs</span></div><div><strong>Genuine products</strong><span>Managed catalogue and real inventory</span></div><div><strong>Clear pricing</strong><span>Transparent pricing before checkout</span></div><div><strong>Easy ordering</strong><span>Cart, checkout and order tracking</span></div></section>
      <section className="section storefront-section"><div className="section-heading"><p className="eyebrow">SHOP BY CATEGORY</p><h2>What are you looking for?</h2><p>Choose a category and find the right products for your job.</p></div><div className="storefront-category-grid">{storefrontCategoryCards.map(category => <button key={category.name} className="storefront-category-card" onClick={() => navigate(category.action)}><span className="storefront-category-icon">{category.icon}</span><div><h3>{category.name}</h3><p>{category.description}</p><strong>Shop now →</strong></div></button>)}</div></section>
      <section className="section storefront-products-strip"><div className="section-heading"><p className="eyebrow">POPULAR PRODUCTS</p><h2>Shop from the catalogue</h2><p>Products added or updated by your admin appear here automatically.</p></div>{productsLoading ? <div className="loading">Loading products…</div> : <div className="products-grid storefront-product-grid">{filteredProducts.slice(0, 8).map(p => <article className="product-card" key={p.id}><div className="product-image">{p.image_url || p.image ? <img src={p.image_url || p.image} alt={p.name}/> : <span>GLASSMART</span>}</div><div className="product-info"><p className="product-category">{p.category}</p><h3>{p.name}</h3><p className="product-description">{p.description}</p><div className="product-pricing"><strong>{money(Number(p.offer_price ?? p.price ?? p.mrp ?? 0))}</strong>{p.mrp && Number(p.mrp) > Number(p.offer_price ?? p.price ?? p.mrp) ? <del>{money(Number(p.mrp))}</del> : null}</div><p className={p.stock > 0 ? "product-stock" : "product-stock out"}>{p.stock > 0 ? `${p.stock} in stock` : "Out of stock"}</p><div className="card-actions"><button className="primary-btn" disabled={p.stock <= 0} onClick={() => addToCart(p)}>Add to cart</button><button className="secondary-btn" onClick={() => { setSelectedProduct(p); navigate("product"); }}>View</button></div></div></article>)}</div>}<div className="storefront-centered-action"><button className="secondary-btn" onClick={() => navigate("products")}>View all products</button></div></section>
      <section className="section storefront-service-banner"><div><p className="eyebrow">PROJECT & SITE SUPPORT</p><h2>Need a custom size, installation or bulk requirement?</h2><p>Send your requirement directly to the team and manage enquiries from the admin dashboard.</p></div><button className="primary-btn" onClick={() => navigate("services")}>Request a quote</button></section>
    </main>}\n'''
app = app[:home_start] + home + app[products_start:]

services_start = app.find('    {page === "services" &&')
contact_start = app.find('    {page === "contact" &&', services_start)
if services_start < 0 or contact_start < 0:
    raise SystemExit("services/contact markers not found")
services = '''    {page === "services" && <main className="services-quote-page"><div className="services-quote-intro"><p className="services-quote-eyebrow">OUR SERVICES</p><h1>Need a Custom Solution?</h1><p>Tell us what you need and our team will get back to you.</p></div><div className="services-quote-card"><div className="services-quote-copy"><p className="services-quote-eyebrow">GET IN TOUCH</p><h2>Request a Quote</h2><p>Whether you're working on a home, restaurant, office or commercial project, tell us about your requirements.</p></div><form className="services-quote-form" onSubmit={async (e) => { e.preventDefault(); if (!enquiry.name || !enquiry.phone || !enquiry.email || !enquiry.service || !enquiry.requirements) { setEnquiryMessage("Please fill in all fields."); return; } setEnquiryLoading(true); setEnquiryMessage(""); const { error } = await supabase.from("enquiries").insert({ name: enquiry.name, phone: enquiry.phone, email: enquiry.email, service: enquiry.service, requirements: enquiry.requirements }); if (error) setEnquiryMessage(error.message); else { setEnquiryMessage("Enquiry submitted successfully. Our team will get back to you."); notify("Enquiry submitted successfully"); setEnquiry({ name: "", phone: "", email: "", service: "", requirements: "" }); } setEnquiryLoading(false); }}><label>Name<input value={enquiry.name} onChange={e => setEnquiry(v => ({ ...v, name: e.target.value }))} placeholder="Your name"/></label><label>Phone<input value={enquiry.phone} onChange={e => setEnquiry(v => ({ ...v, phone: e.target.value }))} placeholder="Phone number"/></label><label>Email<input type="email" value={enquiry.email} onChange={e => setEnquiry(v => ({ ...v, email: e.target.value }))} placeholder="Email address"/></label><label>Service required<select value={enquiry.service} onChange={e => setEnquiry(v => ({ ...v, service: e.target.value }))}><option value="">Select a service</option>{SERVICES.map(service => <option key={service} value={service}>{service}</option>)}</select></label><label className="services-quote-requirements">Requirements<textarea value={enquiry.requirements} onChange={e => setEnquiry(v => ({ ...v, requirements: e.target.value }))} placeholder="Tell us what you need"/></label><div className="services-quote-submit"><button className="primary-btn" type="submit" disabled={enquiryLoading}>{enquiryLoading ? "Submitting..." : "Submit Enquiry"}</button></div>{enquiryMessage && <div className={enquiryMessage.toLowerCase().includes("success") ? "form-success services-quote-message" : "form-error services-quote-message"}>{enquiryMessage}</div>}</form></div></main>}\n'''
app = app[:services_start] + services + app[contact_start:]
app_path.write_text(app, encoding="utf-8")

css_path.write_text(css_path.read_text(encoding="utf-8") + '''\n\n/* Final storefront layout */
.storefront-home{background:#fff}.storefront-hero{display:grid;grid-template-columns:1.05fr .95fr;gap:52px;padding:64px 8% 48px;background:#fff}.storefront-hero-copy{display:flex;flex-direction:column;justify-content:center}.storefront-kicker{margin:0 0 15px;color:var(--red);font-size:12px;font-weight:900;letter-spacing:1.8px}.storefront-hero h1{font-size:56px;line-height:1.04;letter-spacing:-1.5px;color:var(--navy);max-width:700px;margin:0 0 18px}.storefront-hero-copy>p:not(.storefront-kicker){font-size:19px;line-height:1.65;color:#617287;max-width:650px;margin:0 0 28px}.storefront-hero-actions{display:flex;gap:12px;flex-wrap:wrap}.storefront-hero-image{min-height:430px;position:relative;border-radius:16px;overflow:hidden;background:#e9eff4}.storefront-hero-image img{width:100%;height:100%;object-fit:cover}.storefront-hero-tag{position:absolute;left:20px;right:20px;bottom:20px;padding:16px 18px;border-radius:10px;background:#102d4de8;color:#fff;display:flex;justify-content:space-between;gap:15px}.storefront-benefits{display:grid;grid-template-columns:repeat(4,1fr);background:#f7f9fb;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:22px 8%;gap:18px}.storefront-benefits>div{display:flex;flex-direction:column;gap:4px}.storefront-benefits strong{color:var(--navy);font-size:14px}.storefront-benefits span{color:#617287;font-size:13px}.storefront-category-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.storefront-category-card{display:flex;align-items:flex-start;gap:18px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:22px;text-align:left;min-height:165px}.storefront-category-card:hover{border-color:#9eacb9;box-shadow:0 10px 25px #142d4610;transform:translateY(-2px)}.storefront-category-icon{width:58px;height:58px;flex:0 0 58px;border-radius:10px;background:#eef3f7;display:flex;align-items:center;justify-content:center;color:var(--navy);font-size:25px}.storefront-category-card h3{color:var(--navy);margin:2px 0 7px;font-size:20px}.storefront-category-card p{color:#617287;margin:0 0 14px;line-height:1.45;font-size:14px}.storefront-category-card strong{color:var(--red);font-size:13px}.storefront-products-strip{background:#f7f9fb}.storefront-product-grid{grid-template-columns:repeat(4,1fr)}.storefront-centered-action{display:flex;justify-content:center;margin-top:28px}.storefront-service-banner{display:flex;justify-content:space-between;align-items:center;gap:25px;background:#fff;border-top:1px solid var(--line)}.storefront-service-banner h2{font-size:34px;color:var(--navy);margin:6px 0 10px;max-width:820px}.storefront-service-banner p:last-child{color:#617287;max-width:760px;line-height:1.6}.services-quote-page{width:100%;max-width:1450px;margin:auto;padding:52px 5.5% 80px;background:#fff;min-height:680px}.services-quote-intro{margin:0 0 62px}.services-quote-eyebrow{margin:0 0 18px;color:#59728e;font-size:16px;font-weight:900;letter-spacing:5px}.services-quote-intro h1{margin:0 0 18px;color:var(--navy);font-size:60px;line-height:1.08}.services-quote-intro>p:last-child{margin:0;color:#55708d;font-size:23px}.services-quote-card{display:grid;grid-template-columns:.9fr 1.1fr;gap:70px;background:#fff;border:1px solid #d5dde6;border-radius:16px;padding:64px 70px;box-shadow:0 3px 14px #142d4608}.services-quote-copy{padding-top:12px}.services-quote-copy h2{margin:0 0 28px;color:var(--navy);font-size:54px}.services-quote-copy>p:last-child{color:#55708d;font-size:21px;line-height:1.7}.services-quote-form{display:grid;grid-template-columns:1fr 1fr;gap:30px 28px}.services-quote-form label{display:block;color:#123b65;font-size:16px;font-weight:800}.services-quote-form input,.services-quote-form select,.services-quote-form textarea{width:100%;box-sizing:border-box;margin-top:10px;padding:16px 18px;border:1px solid #c7d2df;border-radius:7px;background:#fff;font-size:17px}.services-quote-form input,.services-quote-form select{height:60px}.services-quote-form textarea{height:150px;resize:vertical}.services-quote-requirements,.services-quote-submit,.services-quote-message{grid-column:1/-1}.services-quote-submit .primary-btn{background:#df302f;padding:16px 34px;border-radius:7px;font-size:18px;min-width:218px}@media(max-width:1000px){.storefront-hero{grid-template-columns:1fr}.storefront-benefits{grid-template-columns:repeat(2,1fr)}.storefront-category-grid,.storefront-product-grid{grid-template-columns:repeat(2,1fr)}.services-quote-card{grid-template-columns:1fr;gap:40px;padding:45px}}@media(max-width:650px){.storefront-hero{padding:35px 18px}.storefront-hero h1{font-size:40px}.storefront-hero-image{min-height:290px}.storefront-benefits{grid-template-columns:1fr;padding:18px}.storefront-category-grid,.storefront-product-grid{grid-template-columns:1fr}.storefront-service-banner{display:block}.storefront-service-banner .primary-btn{margin-top:15px;width:100%}.services-quote-page{padding:32px 18px 60px}.services-quote-intro h1{font-size:42px}.services-quote-intro>p:last-child{font-size:18px}.services-quote-card{padding:30px 22px}.services-quote-copy h2{font-size:38px}.services-quote-form{grid-template-columns:1fr}.services-quote-requirements,.services-quote-submit,.services-quote-message{grid-column:auto}.services-quote-submit .primary-btn{width:100%}}
''', encoding="utf-8")
print("Final storefront and services layout applied")
